import { sendToWebEngage } from './webengage'
import { useGetAgentDetails } from '../../state/globalState/hooks/useGlobalContext'
import { getDeviceType } from '../../helpers/utility'
import { getAgentType, getDeviceByScreenSize, getSourceString, getIsRm } from './helpers'

function useEventTracker() {
  const [globalState] = useGetAgentDetails()
  const getAgentDetailData = globalState?.getAgentDetailData

  const getCommonData = () => {
    return {
      agent_id: getAgentDetailData?.agent_code || 'unknown',
      agent_type: getAgentType(getAgentDetailData),
      is_rm: getIsRm(getAgentDetailData),
      screen_size: getDeviceByScreenSize(),
      device_type: getDeviceType(),
      source: getSourceString(),
    }
  }

  const trackUserEvent = (eventName, data = {}) => {
    try {
      const commonData = getCommonData()
      const eventData = { ...commonData, ...data }

      sendToWebEngage(eventName, eventData)
    } catch (error) {
      console.error('Tracker error:', error)
    }
  }

  return { trackUserEvent }
}

export default useEventTracker
