import { useMemo } from 'react'
import { useGlobalContextValue } from '../../../../../../../../contextProvider/GlobalContext'
import {
  getPaymentExpiryPill,
  getPaymentStatusPill,
  getPolicyStatusPill,
  getRenewalExpiryPill,
} from './helpers'
import { CardContainer } from './index.style'

const CARD_TYPE = {
  RENEWAL: 'RENEWAL',
  PAYMENT: 'PAYMENT',
  DEFAULT: 'DEFAULT',
}

function PolicyApplicationCard({ type = CARD_TYPE.DEFAULT, policyData, onClickCard }) {
  const [{ productIconData }] = useGlobalContextValue()

  const policyStatusPill = useMemo(() => getPolicyStatusPill(policyData), [policyData])
  const paymentStatusPill = useMemo(() => getPaymentStatusPill(policyData), [policyData])
  const paymentExpiryPill = useMemo(() => getPaymentExpiryPill(policyData), [policyData])
  const renewalExpiryPill = useMemo(() => getRenewalExpiryPill(policyData), [policyData])

  return (
    <CardContainer
      role="button"
      tabIndex={0}
      onClick={onClickCard}
      data-testid="policy-application-card"
    >
      <div className="left">
        <div className="icon-wrap">
          <img src={productIconData?.[policyData?.product_key]} alt="" />
        </div>
      </div>

      <div className="content-container">
        <div className="content">
          <div>
            <div className="provider-name">{policyData?.insurance_provider}</div>
            <div className="customer-name">{policyData?.title}</div>
            <div className="application-no">{policyData?.application_no}</div>
          </div>
          {type === CARD_TYPE.RENEWAL && <div className="status">{renewalExpiryPill}</div>}
          {type === CARD_TYPE.PAYMENT && <div className="status">{paymentExpiryPill}</div>}
          {type === CARD_TYPE.DEFAULT && (
            <div className="status">
              {policyStatusPill}
              {paymentStatusPill}
            </div>
          )}
        </div>
      </div>
    </CardContainer>
  )
}

export default PolicyApplicationCard
