export const usePolicyServiceCall = (actionsCall = () => {}) => {
  const [policyState, dispatch] = usePolicyContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(
    async (payload = {}) => {
      await callApi(
        actionsCall({
          ...payload,
        })
      )
    },
    [callApi, actionsCall]
  )

  return [policyState, request]
}

