export const useUpdateDiscount = () => {
  const [state, dispatch] = usePolicyContextValue()
  const update = useCallback((discount) => dispatch(updateDiscount(discount)), [dispatch])
  return [state, update]
}

// use setPolicy state
export const useSetPolicyState = () => {
  const [, dispatch] = usePolicyContextValue()
  return useCallback(
    (payload) => {
      dispatch(setPolicyState(payload))
    },
    [dispatch]
  )
}

// this is the province and city data
export const useProvinceCityData = (citiesRef, isMVApplication, provinceCode) => {
  const [{ getProvinceData }, getProvincesRequest] = useGetProvince()
  const [{ getCitiesData }, getCitiesRequest] = useGetCities()
  const [{ GET_PROVINCE_LOADER }] = useLoaderContextValue()
  const that = useRef({
    isInitialCitiesCall: !!provinceCode,
  })

  const handleProvinceSelect = useCallback(
    (provinceCode) => {
      if (provinceCode) {
        getCitiesRequest({ province: provinceCode })
        if (citiesRef.current) {
          citiesRef.current.resetModalState()
        }
      }
    },
    [getCitiesRequest, citiesRef]
  )

  useEffect(() => {
    if (!isMVApplication && GET_PROVINCE_LOADER === undefined) {
      getProvincesRequest()
    }

    if (provinceCode && that.current.isInitialCitiesCall) {
      that.current.isInitialCitiesCall = false
      handleProvinceSelect(provinceCode)
    }
  }, [
    getProvincesRequest,
    GET_PROVINCE_LOADER,
    isMVApplication,
    provinceCode,
    handleProvinceSelect,
  ])

  return {
    getCitiesData,
    getProvinceData,
    handleProvinceSelect,
  }
}

