export const useValidatePolicyData = ({ onCall = () => {}, errorMsg }) => {
  const [{ validateChassisNoData = {} }, validateChassisNoRequest] = useValidateChassisNumber()
  const [{ VALIDATE_CHASSIS_NO_LOADER }] = useLoaderContextValue()
  const [{ validateChassisNoStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const that = useRef({})
  const timer = useRef({})
  const apiCount = useRef(3)
  const data = useRef({})

  const getPreValidateKeys = useCallback(() => {
    const { preValidateData, policy } = data.current
    for (const key in preValidateData) {
      that.current[key] = {}
      const keyItem = preValidateData[key] || []
      keyItem.forEach((propKeys) => {
        that.current[key][propKeys] = policy[propKeys]
      })
    }

    return that.current
  }, [])

  const validatePolicyData = useCallback(() => {
    validateChassisNoRequest({
      body: {
        code: data.current.policy?.code,
        identifier_value: data.current.policy?.reference_id.replaceAll('-', ''),
        identifier: 'reference_id',
        pre_validate_data: {
          ...getPreValidateKeys(),
        },
      },
    })
  }, [getPreValidateKeys, validateChassisNoRequest])

  const initiateValidateReq = useCallback(
    ({ policy, preValidateData = {} }) => {
      data.current = {
        policy,
        preValidateData,
      }
      if (timer.current) {
        clearTimeout(timer.current)
        timer.current = ''
      }
      timer.current = setTimeout(() => {
        validatePolicyData()
        timer.current = ''
      }, 5000)
    },
    [validatePolicyData]
  )

  const checkTheNextCallTime = useCallback(
    (data) => {
      const nextCallTimeMs = new Date(data.tentative_timestamp) - new Date(data.enquiry_timestamp)
      if (nextCallTimeMs > 15000) {
        if (timer.current) {
          clearTimeout(timer.current)
          timer.current = ''
        }
        timer.current = setTimeout(() => {
          validatePolicyData()
        }, 15000)
      }
    },
    [validatePolicyData]
  )

  useEffect(() => {
    // validate chassis number
    if (validateChassisNoStatus === 'success') {
      // check is data is ok if not then show error
      if (!validateChassisNoData.success) {
        onCall({
          error: !validateChassisNoData.success,
          isEdit: true,
        })
        ShowSnackbar.error({
          visible: true,
          text: errorMsg,
        })
      } else if (validateChassisNoData.is_request_pending) {
        onCall({
          isRequestPending: true,
          ...validateChassisNoData,
        })
        checkTheNextCallTime(validateChassisNoData.data)
      } else {
        // handle the form data here
        // with new chassis number
        onCall({
          isRequestPending: false,
          ...validateChassisNoData,
        })
      }
      resetError(['validateChassisNoStatus'])
    } else if (validateChassisNoStatus) {
      if (!apiCount.current) {
        ShowSnackbar.error({
          visible: true,
          text: validateChassisNoStatus,
        })
      } else {
        apiCount.current -= 1
        validatePolicyData()
      }
      resetError(['validateChassisNoStatus'])
    }
  }, [
    resetError,
    validatePolicyData,
    errorMsg,
    validateChassisNoStatus,
    validateChassisNoData,
    checkTheNextCallTime,
    onCall,
  ])

  return {
    validateChassisNoData,
    initiateValidateReq,
    isLoader: VALIDATE_CHASSIS_NO_LOADER || validateChassisNoData.is_request_pending,
  }
}

